    old, c = nb.selected, nb.get(id)
    if c is None: return ''
    nb.selected = id
    old_c = nb.get(old) if (old is not None and old != id) else None
    return (render_cell(c), render_cell(old_c, oob=True)) if old_c is not None else render_cell(c)


